'use client'

import { useState, useEffect, useRef, useSyncExternalStore, type ReactNode, type FormEvent } from 'react'
import { LayoutDashboard, Package, BookOpen, ClipboardList, ShoppingCart, Truck, Trash2, Settings, Search, Plus, ArrowUpRight, ArrowRight, ChevronRight, Check, CheckCircle2, AlertCircle, Download, Upload, X, Loader2, Pencil, RefreshCw, ShieldCheck, ChefHat, Play, CalendarDays, MoreHorizontal, ExternalLink, Menu, Info, Leaf, Database, CheckCheck, FolderArchive } from 'lucide-react'
import { costRecipe, createDraftOrders, emptyWorkspace, sampleWorkspace, receiveOrder, stockStatus, unitCost, kitchenDay, money, quantity, workspaceSchema, type Snapshot, type Workspace, type Recipe, type Order } from '@/lib/workspace/domain'
import { csv, download, inventoryCsv, inventoryHeaders, importInventory } from '@/lib/workspace/import-export'
import { FormDialog, Field, IngredientEditor, RecipeEditor, SupplierEditor, PrepEditor, WasteEditor } from './editors'
import { FabergeData } from './faberge-data'
import { BusinessPlanner, MenuLaunch, SetupGuide, FirstKitchen } from './business-planner'
import { Subscription } from './subscription'
import { demoWorkspace } from '@/lib/workspace/demo'
import { Wallet, Rocket, CreditCard } from 'lucide-react'
import './workspace.css'
import './professional.css'

const views = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard, eyebrow: 'THE DAILY PICTURE', description: 'A clear kitchen. A calmer service.' },
  { id: 'inventory', label: 'Inventory', icon: Package, eyebrow: 'KNOW WHAT YOU HAVE', description: 'Your stock, purchase prices, and par levels.' },
  { id: 'recipes', label: 'Recipe costing', icon: BookOpen, eyebrow: 'KNOW YOUR MARGINS', description: 'Understand the cost of every plate.' },
  { id: 'prep', label: 'Prep board', icon: ClipboardList, eyebrow: 'READY FOR SERVICE', description: 'The right prep, in the right hands.' },
  { id: 'orders', label: 'Purchase orders', icon: ShoppingCart, eyebrow: 'KEEP THE KITCHEN STOCKED', description: 'From low stock to a received delivery.' },
  { id: 'suppliers', label: 'Suppliers', icon: Truck, eyebrow: 'YOUR SUPPLY NETWORK', description: 'Contacts and delivery details, together.' },
  { id: 'waste', label: 'Waste log', icon: Leaf, eyebrow: 'MAKE EVERY INGREDIENT COUNT', description: 'See what leaves the kitchen unused.' },
  { id: 'sales', label: 'Sales history', icon: LayoutDashboard, eyebrow: 'YOUR RECORDED SALES', description: 'POS item history and separate report controls.' },
  { id: 'team', label: 'Staffing & payroll', icon: CalendarDays, eyebrow: 'YOUR TEAM & LABOUR', description: 'Draft roster and recorded payroll periods.' },
  { id: 'budget', label: 'Labour & budget', icon: Wallet, eyebrow: 'PLAN THE BUSINESS', description: 'Your annual hiring cost and monthly break-even scenario.' },
  { id: 'launch', label: 'Menu launch', icon: Rocket, eyebrow: 'READY FOR THE NEXT SERVICE', description: 'Take your menu from approval to its first week.' },
  { id: 'sources', label: 'Source library', icon: FolderArchive, eyebrow: 'YOUR ORIGINAL DATA', description: 'Your workbooks, recipes, reports, and import notes.' },
  { id: 'billing', label: 'Subscription', icon: CreditCard, eyebrow: 'YOUR MISE PLAN', description: 'Manage subscription access and billing.' },
  { id: 'settings', label: 'Settings', icon: Settings, eyebrow: 'YOUR KITCHEN, YOUR WAY', description: 'Set your target and look after your records.' },
] as const
type View = typeof views[number]['id']
type Modal = { type: 'ingredient' | 'recipe' | 'task' | 'supplier' | 'waste' | 'detail' | 'order' | 'import' | 'sample' | 'reset'; id?: string }
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'good' | 'warning' | 'blue' }) { return <span className={`badge ${tone}`}>{children}</span> }
function Empty({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{text}</p>{action}</div> }
function SectionTitle({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) { return <div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div> }
function getView(): View { const value = new URLSearchParams(window.location.search).get('view'); return views.some(v => v.id === value) ? value as View : 'overview' }
function subscribeView(listener:()=>void){window.addEventListener('popstate',listener);window.addEventListener('mise-view',listener);return()=>{window.removeEventListener('popstate',listener);window.removeEventListener('mise-view',listener)}}
async function loadSnapshot(demo:boolean,signal:AbortSignal):Promise<Snapshot> {
  if(demo){
    let state=demoWorkspace()
    try{const saved=sessionStorage.getItem('mise-product-demo-v1');if(saved)state=workspaceSchema.parse(JSON.parse(saved))}catch{/* A damaged demo session starts fresh. */}
    return {revision:1,state,updatedAt:null}
  }
  const response=await fetch('/api/workspace',{cache:'no-store',signal})
  const body=await response.json()
  if(!response.ok)throw new Error(body.error??'Your kitchen could not be loaded.')
  return {...body,state:workspaceSchema.parse(body.state)}
}

export default function KitchenWorkspace({ displayName, mode='live' }: { displayName: string; mode?:'live'|'demo' }) {
  const demo=mode==='demo'
  const urlView=useSyncExternalStore(subscribeView,getView,()=>'overview' as View)
  const view=demo&&['sales','team','sources'].includes(urlView)?'overview':urlView
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null)
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState('')
  const [busy, setBusy] = useState(false)
  const saving = useRef(false)
  const [search, setSearch] = useState('')
  const [filter, setFilter] = useState('all')
  const [modal, setModal] = useState<Modal | null>(null)
  const [notice, setNotice] = useState('')
  const [mobileOpen, setMobileOpen] = useState(false)
  const [importData, setImportData] = useState<{ state: Workspace; name: string; kind: 'inventory' | 'backup' } | null>(null)
  const fileInput = useRef<HTMLInputElement>(null)
  const backupInput = useRef<HTMLInputElement>(null)
  const searchInput = useRef<HTMLInputElement>(null)
  const today = kitchenDay()
  const state = snapshot?.state ?? emptyWorkspace()
  const current = views.find(v => v.id === view)!
  const q = search.trim().toLowerCase()
  const matches = (value: string) => !q || value.toLowerCase().includes(q)

  async function reload() {
    if (saving.current) return
    setLoading(true); setLoadError(''); setModal(null)
    try {
      setSnapshot(await loadSnapshot(demo,AbortSignal.timeout(20000)))
    } catch (error) { setLoadError(error instanceof Error ? error.message : 'Your kitchen could not be loaded.') }
    finally { setLoading(false) }
  }
  useEffect(() => {
    const controller=new AbortController()
    loadSnapshot(demo,AbortSignal.any([controller.signal,AbortSignal.timeout(20000)]))
      .then(result=>{if(!controller.signal.aborted)setSnapshot(result)})
      .catch(error=>{if(!controller.signal.aborted)setLoadError(error instanceof Error?error.message:'Your kitchen could not be loaded.')})
      .finally(()=>{if(!controller.signal.aborted)setLoading(false)})
    const pop=()=>{setSearch('');setFilter('all')}
    window.addEventListener('popstate',pop)
    return ()=>{controller.abort();window.removeEventListener('popstate',pop)}
  },[demo])
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 6000); return () => clearTimeout(timer) }, [notice])
  useEffect(() => { const key = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); searchInput.current?.focus() } }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key) }, [])
  function navigate(next: View) { setSearch(''); setFilter('all'); setMobileOpen(false); const url = new URL(window.location.href); if (next === 'overview') url.searchParams.delete('view'); else url.searchParams.set('view', next); window.history.pushState({}, '', url);window.dispatchEvent(new Event('mise-view')); window.scrollTo(0, 0) }
  async function save(next: Workspace): Promise<boolean> {
    if (saving.current || !snapshot || loading || loadError) return false
    const parsed = workspaceSchema.safeParse(next)
    if (!parsed.success) { setNotice(parsed.error.issues[0].message); return false }
    saving.current = true; setBusy(true)
    try {
      if(demo){
        sessionStorage.setItem('mise-product-demo-v1',JSON.stringify(parsed.data))
        setSnapshot({revision:snapshot.revision+1,state:parsed.data,updatedAt:new Date().toISOString()});setNotice('Demo changes saved in this browser session.');return true
      }
      const response = await fetch('/api/workspace', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ revision: snapshot.revision, state: parsed.data }), signal: AbortSignal.timeout(20000) })
      const body = await response.json()
      if (!response.ok) throw new Error(body.error ?? 'Saving failed. Please retry.')
      setSnapshot(body); setNotice('Saved to your private kitchen.'); return true
    } catch (error) { setNotice(error instanceof Error ? error.message : 'Saving failed. Please retry.'); return false }
    finally { saving.current = false; setBusy(false) }
  }
  const low = state.ingredients.filter(i => stockStatus(i) === 'low')
  const uncounted = state.ingredients.filter(i => i.stock === null)
  const costed = state.recipes.map(recipe => ({ recipe, cost: costRecipe(recipe, state.ingredients, state.settings.targetFoodCost) }))
  const completedCosts = costed.filter(r => r.cost.foodCost !== null)
  const needsCost = costed.filter(r => r.cost.status === 'incomplete')
  const reviewCosts = costed.filter(r => r.cost.status === 'review')
  const activePrep = state.prep.filter(p => p.due !== null && p.due <= today && p.status !== 'done')
  const todaysPrep = state.prep.filter(p => p.due === today || (p.due !== null && p.due < today && p.status !== 'done'))
  const prepReady = todaysPrep.filter(p => p.status === 'done').length
  const openOrders = state.orders.filter(o => o.status !== 'received')
  const monthWaste = state.waste.filter(w => w.date.slice(0, 7) === today.slice(0, 7) && w.date <= today)
  const inventoryValue = state.ingredients.length > 0 && state.ingredients.every(i => i.stock !== null && (i.stock === 0 || unitCost(i) !== null))
    ? state.ingredients.reduce((sum, i) => sum + (i.stock! * (unitCost(i) ?? 0)), 0)
    : null
  const ingredientCostMissing = state.ingredients.filter(i => unitCost(i) === null)
  const disabled = busy || loading || !!loadError || !snapshot
  const primaryButton = (type: Modal['type'], label: string) => <button className="button primary" disabled={disabled} onClick={() => setModal({ type })}><Plus size={17}/>{label}</button>
  const pagePrimary = view === 'inventory' ? primaryButton('ingredient', 'Add ingredient') : view === 'recipes' ? primaryButton('recipe', 'Add recipe') : view === 'prep' ? primaryButton('task', 'Add prep task') : view === 'suppliers' ? primaryButton('supplier', 'Add supplier') : view === 'waste' ? primaryButton('waste', 'Record waste') : null
  async function draftOrders() { const orders = createDraftOrders(state); if (!orders.length) { setNotice('No new order lines. Low-stock items need pack pricing and a stock count, and must not already be on an open order.'); return }; if (await save({ ...state, orders: [...orders, ...state.orders] })) navigate('orders') }
  async function deleteRecord(kind: 'ingredients' | 'recipes' | 'suppliers' | 'prep', id: string) {
    if (kind === 'ingredients' && (state.recipes.some(r => r.items.some(i => i.ingredientId === id)) || state.waste.some(w => w.ingredientId === id) || state.orders.some(o => o.lines.some(l => l.ingredientId === id)))) { setNotice('This ingredient is used in a recipe, order, or waste record. Keep it to preserve those records.'); return }
    if (kind === 'suppliers' && (state.ingredients.some(i => i.supplierId === id) || state.orders.some(o => o.supplierId === id))) { setNotice('This supplier is linked to ingredients or orders. Reassign ingredients first; saved order history must be preserved.'); return }
    if (window.confirm('Delete this record?')) await save({ ...state, [kind]: state[kind].filter(r => r.id !== id) })
  }
  function exportTable() {
    let content = '', filename = ''
    if (view === 'inventory') { content = inventoryCsv(state); filename = 'inventory' }
    if (view === 'recipes') { content = csv([['recipe','category','batch_portions','selling_price_cad','batch_cost_cad','portion_cost_cad','food_cost_pct','contribution_cad','price_at_target_cad','status','missing_inputs'], ...costed.map(({ recipe, cost }) => [recipe.name,recipe.category,recipe.portions,recipe.sellingPrice,cost.batchCost,cost.portionCost,cost.foodCost,cost.contribution,cost.suggestedPrice,cost.status,cost.issues.join('; ')])]); filename = 'recipe-costing' }
    if (view === 'waste') { content = csv([['date','ingredient','quantity','unit','reason','cost_cad'], ...state.waste.map(w => [w.date,state.ingredients.find(i => i.id === w.ingredientId)?.name,w.quantity,w.unit,w.reason,w.cost])]); filename = 'waste' }
    if (view === 'prep') { content = csv([['task','station','assigned_to','quantity','due_date','priority','status'], ...state.prep.map(p => [p.name,p.station,p.assignee,p.quantity,p.due,p.priority,p.status])]); filename = 'prep' }
    if (view === 'suppliers') { content = csv([['supplier','contact','email','phone','delivery_days','notes'], ...state.suppliers.map(s => [s.name,s.contact,s.email,s.phone,s.deliveryDays,s.notes])]); filename = 'suppliers' }
    if (view === 'orders') { content = csv([['order_id','supplier','created','status','received','ingredient','packs','purchase_pack','pack_price_cad','line_cost_cad'], ...state.orders.flatMap(o => o.lines.map(l => [o.id,state.suppliers.find(s => s.id === o.supplierId)?.name ?? 'Unassigned',o.created,o.status,o.received,l.name,l.packs,l.purchaseLabel,l.unitPrice,l.packs*l.unitPrice]))]); filename = 'orders' }
    if (content) download(content, `mise-${filename}-${today}.csv`, 'text/csv;charset=utf-8')
  }
  async function readImport(file: File | undefined, kind: 'inventory' | 'backup') {
    if (!file || disabled) return
    try {
      if (file.size > 2_000_000) throw new Error('Choose a file smaller than 2 MB.')
      const source = await file.text()
      const next = kind === 'inventory' ? importInventory(source, state) : workspaceSchema.parse(JSON.parse(source))
      workspaceSchema.parse(next)
      setImportData({ state: next, name: file.name, kind }); setModal({ type: 'import' })
    } catch (error) { setNotice(error instanceof Error ? error.message : 'This file could not be imported.') }
  }
  const editorProps = { state, id: modal?.id, busy, save, close: () => setModal(null), notify: setNotice }
  const anyRecords = !!(state.ingredients.length || state.recipes.length || state.prep.length || state.suppliers.length)

  return <div className="kitchen-app">
    {mobileOpen && <button className="mobile-backdrop" aria-label="Close navigation" onClick={() => setMobileOpen(false)}/>}
    <a href="#kitchen-main" className="skip-link">Skip to content</a>
    <aside className={`kitchen-sidebar ${mobileOpen ? 'mobile-open' : ''}`}><a href="/" className="brand" onClick={e => { e.preventDefault(); navigate('overview') }}><span className="brand-mark"><ChefHat size={22}/></span><span>mise<span className="brand-dot">.</span><small>KITCHEN OPERATIONS</small></span></a>
      <div className="kitchen-switch"><span className="kitchen-avatar">{state.settings.kitchenName.charAt(0).toUpperCase()}</span><div><strong>{state.settings.kitchenName}</strong><small>Kitchen workspace</small></div><ShieldCheck size={15}/></div>
      <div className="nav-label">YOUR WORKSPACE</div><nav aria-label="Kitchen navigation">{views.filter(item=>!demo||!['sales','team','sources'].includes(item.id)).map(item => <button key={item.id} className={`nav-item ${view === item.id ? 'active' : ''}`} aria-current={view === item.id ? 'page' : undefined} onClick={() => navigate(item.id)}><item.icon size={18}/><span>{item.label}</span>{item.id === 'inventory' && low.length > 0 && <em>{low.length}</em>}{item.id === 'prep' && activePrep.length > 0 && <em>{activePrep.length}</em>}</button>)}</nav>
      <div className="sidebar-note"><span className="note-symbol"><Leaf size={19}/></span><strong>Built for better service.</strong><p>Small checks. Clear decisions.</p><a href="/product">Explore Mise <ArrowUpRight size={14}/></a></div>
      <div className="sidebar-bottom"><span className="user-avatar">{displayName.charAt(0).toUpperCase()}</span><div><strong>{displayName.includes('@') ? displayName.split('@')[0] : displayName}</strong><small><ShieldCheck size={11}/>{demo?'Demo session':'Private workspace'}</small></div><a href={demo?'/product':'/signout-with-chatgpt?return_to=%2F'} target="_top" aria-label={demo?'Leave demo':'Sign out'} title={demo?'Leave demo':'Sign out'}><ExternalLink size={15}/></a></div>
    </aside>
    <div className="kitchen-content"><header className="kitchen-topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" onClick={() => setMobileOpen(true)} aria-label="Open navigation"><Menu size={20}/></button><span>Workspace</span><ChevronRight size={13}/><strong>{current.label}</strong></div><div className="topbar-right"><span className="cloud-state">{loading || busy ? <Loader2 size={14} className="spin"/> : loadError ? <AlertCircle size={14}/> : <CheckCircle2 size={14}/>}<span>{loading ? 'Loading' : busy ? 'Saving' : loadError ? 'Unavailable' : snapshot?.updatedAt ? 'Saved' : 'Ready'}</span></span><button className="icon-button" onClick={() => void reload()} disabled={busy || loading} aria-label="Reload kitchen" title="Reload from cloud"><RefreshCw size={16}/></button><span className="topbar-divider"/><span className="date-label"><CalendarDays size={15}/>{new Date(`${today}T12:00:00`).toLocaleDateString('en-CA', { month: 'short', day: 'numeric' })}</span></div></header>
    <main className="kitchen-main" id="kitchen-main"><div className="page-heading"><div><span className="eyebrow">{current.eyebrow}</span><h1>{view === 'overview' ? 'Your kitchen, in sync' : current.label}<span className="heading-dot">.</span></h1><p>{current.description}</p></div><div className="heading-actions">{view === 'overview' ? <><button className="button secondary" disabled={disabled} onClick={() => navigate('prep')}><ClipboardList size={16}/>View prep board</button>{primaryButton('task', 'Add prep task')}</> : pagePrimary}</div></div>
      {demo&&<div className="demo-banner"><span><strong>Product demo</strong> · Illustrative kitchen. Changes stay in this browser session.</span><button onClick={()=>{sessionStorage.removeItem('mise-product-demo-v1');void reload()}}>Reset demo</button><a href="/">Open my workspace<ArrowUpRight size={14}/></a></div>}
      {state.sampleData && <div className="sample-banner"><Info size={16}/><span><strong>Sample kitchen</strong> · All prices, quantities, and recipes are illustrative. Replace them before using the results.</span><button onClick={() => navigate('settings')}>Manage sample <ArrowRight size={14}/></button></div>}
      {loading ? <div className="loading-panel"><Loader2 className="spin" size={26}/><h2>Opening your kitchen</h2><p>Loading your saved records.</p></div> : loadError ? <div className="error-panel" role="alert"><AlertCircle size={30}/><h2>Your kitchen couldn’t be loaded</h2><p>{loadError}</p><button className="button primary" onClick={() => void reload()}><RefreshCw size={16}/>Retry</button></div> : <>
      {view === 'overview' && <>
        {!anyRecords&&<FirstKitchen state={state} busy={busy} save={save}/>}
        <SetupGuide state={state} navigate={navigate}/>
        <div className="metric-grid"><Metric icon={<Package size={18}/>} label="Stock value" value={money(inventoryValue)} note={ingredientCostMissing.length ? `${ingredientCostMissing.length} ingredients need pricing` : `${state.ingredients.length} ingredients in your kitchen`} onClick={() => navigate('inventory')}/><Metric icon={<BookOpen size={18}/>} label="Average food cost" value={completedCosts.length ? `${(completedCosts.reduce((sum, r) => sum + r.cost.foodCost!, 0) / completedCosts.length).toFixed(1)}%` : '—'} note={`${completedCosts.length} fully costed recipes · target ${state.settings.targetFoodCost}%`} onClick={() => navigate('recipes')}/><Metric icon={<ClipboardList size={18}/>} label="Prep ready" value={`${prepReady} / ${todaysPrep.length}`} note={activePrep.length ? `${activePrep.length} tasks waiting for the team` : 'No outstanding prep for today'} onClick={() => navigate('prep')}/><Metric icon={<ShoppingCart size={18}/>} label="Open orders" value={String(openOrders.length).padStart(2, '0')} note={low.length ? `${low.length} ingredients below par` : 'No stock alerts from counted ingredients'} onClick={() => navigate('orders')}/></div>
        {!demo&&state.ingredients.some(i=>i.source) && <div className="import-banner"><FolderArchive size={22}/><div><strong>Your imported records, together</strong><p>Original files, historical reports and input notes are available in your source library.</p></div><button className="button secondary small" onClick={()=>navigate('sources')}>View sources<ArrowRight size={15}/></button></div>}
        <div className="overview-grid"><section className="panel prep-panel"><SectionTitle title="Today’s mise en place" subtitle="Today’s tasks and unfinished prep from earlier days." action={<button className="text-button" onClick={() => navigate('prep')}>View board <ArrowUpRight size={15}/></button>}/><div className="prep-progress"><span>{prepReady} of {todaysPrep.length} ready</span><strong>{todaysPrep.length ? Math.round(prepReady / todaysPrep.length * 100) : 0}%</strong><div><i style={{ width: `${todaysPrep.length ? prepReady / todaysPrep.length * 100 : 0}%` }}/></div></div>{todaysPrep.length ? <div className="prep-list">{[...todaysPrep].sort((a,b) => Number(a.status === 'done') - Number(b.status === 'done') || (a.due ?? '9999').localeCompare(b.due ?? '9999')).slice(0, 5).map(task => <div className={`prep-row ${task.status === 'done' ? 'completed' : ''}`} key={task.id}><button className={`task-check ${task.status === 'done' ? 'checked' : ''}`} aria-label={`${task.status === 'done' ? 'Reopen' : 'Complete'} ${task.name}`} disabled={busy} onClick={() => void save({ ...state, prep: state.prep.map(t => t.id === task.id ? { ...t, status: t.status === 'done' ? 'todo' : 'done' } : t) })}>{task.status === 'done' && <Check size={14}/>}</button><div><button className="item-name" onClick={() => setModal({ type: 'task', id: task.id })}>{task.name}</button><small>{task.station}{task.quantity && ` · ${task.quantity}`}{task.due !== null && task.due < today && ` · overdue ${task.due}`}</small></div><span className="prep-assignee">{task.assignee || 'Unassigned'}</span>{task.priority === 'high' && task.status !== 'done' && <span className="priority-dot" title="High priority"/>}</div>)}</div> : <Empty icon={<ClipboardList size={27}/>} title="Start with today’s prep" text="Give each task a station, quantity, and owner." action={<button className="text-button" onClick={() => setModal({ type: 'task' })}>Add a task <Plus size={15}/></button>}/>}</section>
        <section className="panel attention-panel"><SectionTitle title="Needs your attention" subtitle="Small checks before a busy service."/><div className="attention-list"><Attention icon={<Package size={19}/>} tone="warning" title={`${low.length} ingredients below par`} text={low.length ? low.slice(0,3).map(i => i.name).join(', ') : 'Count your stock and set pars to enable alerts.'} onClick={() => { navigate('inventory'); setFilter('low') }}/><Attention icon={<BookOpen size={19}/>} tone="blue" title={`${needsCost.length} recipes need inputs`} text={needsCost.length ? 'Complete quantities and pricing to see reliable costs.' : 'Incomplete recipes stay clearly marked.'} onClick={() => { navigate('recipes'); setFilter('incomplete') }}/><Attention icon={<AlertCircle size={19}/>} tone="warning" title={`${reviewCosts.length} recipes above target`} text={`Review portion cost against your ${state.settings.targetFoodCost}% target.`} onClick={() => { navigate('recipes'); setFilter('review') }}/>{uncounted.length > 0 && <Attention icon={<ClipboardList size={19}/>} tone="blue" title={`${uncounted.length} ingredients need a count`} text="An unknown quantity is never treated as zero stock." onClick={() => navigate('inventory')}/>}</div></section></div>
        <section className="panel"><SectionTitle title="A closer look at your menu" subtitle="Live costing from your current ingredient prices." action={<button className="text-button" onClick={() => navigate('recipes')}>All recipes <ArrowUpRight size={15}/></button>}/>{costed.length ? <RecipeTable rows={costed.slice(0,4)} inspect={id => setModal({ type:'detail',id })} edit={id => setModal({ type:'recipe',id })} busy={busy}/> : <div className="menu-empty"><BookOpen size={24}/><div><strong>Your recipes belong here.</strong><p>Start with one dish. Add its ingredients and portions, and the costs will follow.</p></div><button className="button secondary" onClick={() => setModal({ type:'recipe' })}>Cost a recipe <ArrowRight size={15}/></button></div>}</section>
        <div className="overview-footnote"><ShieldCheck size={14}/>Your records are saved privately to your account.<span>CAD · Montréal time</span></div>
      </>}
      {!['overview','settings','sales','team','sources'].includes(view) && <div className="table-toolbar"><div className="search-box"><Search size={17}/><input ref={searchInput} aria-label={`Search ${current.label.toLowerCase()}`} value={search} onChange={e => setSearch(e.target.value)} placeholder={`Search ${current.label.toLowerCase()}…`}/><kbd>⌘ K</kbd></div><div className="toolbar-actions">{view === 'inventory' && <button className="button secondary small" disabled={busy} onClick={() => fileInput.current?.click()}><Upload size={15}/>Import CSV</button>}<button className="button secondary small" onClick={exportTable}><Download size={15}/>Export all CSV</button></div></div>}
      {view === 'inventory' && <>
        <div className="filter-row"><div className="filter-tabs">{[['all','All ingredients',state.ingredients.length],['low','Below par',low.length],['unknown','Need a count',uncounted.length]].map(([key,label,count]) => <button key={key} className={filter === key ? 'selected' : ''} onClick={() => setFilter(String(key))}>{label}<span>{count}</span></button>)}</div><button className="text-button" disabled={busy} onClick={() => void draftOrders()}>Build orders from par <ArrowRight size={15}/></button></div>
        <section className="panel table-panel">{!state.ingredients.length ? <Empty icon={<Package size={34}/>} title="Build your inventory" text="Add the pack size and invoice price once. Every recipe uses the same source of pricing." action={primaryButton('ingredient','Add ingredient')}/> : <div className="table-scroll"><table><thead><tr><th>Ingredient</th><th>Purchase pack</th><th className="numeric">Pack price</th><th className="numeric">Usable unit cost</th><th className="numeric">On hand / par</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{state.ingredients.filter(i => matches(`${i.name} ${i.category}`) && (filter === 'all' || filter === 'low' && stockStatus(i) === 'low' || filter === 'unknown' && i.stock === null)).map(i => <tr key={i.id}><td><button className="item-name" onClick={() => setModal({ type:'ingredient',id:i.id })}>{i.name}</button><small>{i.category} · {state.suppliers.find(s => s.id === i.supplierId)?.name ?? 'No supplier'}</small></td><td>{i.purchaseLabel || 'Pack not described'}<small>{quantity(i.packQuantity, i.baseUnit)} · {i.yieldPct}% yield</small></td><td className="numeric">{money(i.price)}</td><td className="numeric">{money(unitCost(i), 4)}<small>per {i.baseUnit}</small></td><td className="numeric">{quantity(i.stock, i.baseUnit)}<small>Par: {i.par === null ? 'Not set' : quantity(i.par, i.baseUnit)}</small></td><td><Badge tone={stockStatus(i) === 'low' ? 'warning' : stockStatus(i) === 'healthy' ? 'good' : 'neutral'}>{stockStatus(i) === 'low' ? 'Below par' : stockStatus(i) === 'healthy' ? 'Stock OK' : 'Needs count / par'}</Badge>{i.source && <small className={i.source.status==='confirmed'?'':'warning-text'}>{i.source.status==='confirmed'?'Imported price':i.source.status==='estimate'?'Estimated pack · confirm':'Source needs review'}{i.source.priceDate && ` · ${i.source.priceDate}`}</small>}{unitCost(i) === null && <small className="warning-text">Missing price / pack size</small>}</td><td><div className="row-actions"><button className="icon-button" disabled={busy} aria-label={`Edit ${i.name}`} onClick={() => setModal({ type:'ingredient',id:i.id })}><Pencil size={15}/></button><button className="icon-button" disabled={busy} aria-label={`Delete ${i.name}`} onClick={() => void deleteRecord('ingredients',i.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table>{!state.ingredients.some(i => matches(`${i.name} ${i.category}`) && (filter === 'all' || filter === 'low' && stockStatus(i) === 'low' || filter === 'unknown' && i.stock === null)) && <div className="no-results">No ingredients match this view.</div>}</div>}</section><div className="inline-page-note"><Info size={15}/>Stock and par are usable quantities in the base unit. Purchase quantities describe the whole pack.<button className="text-button" onClick={() => download(csv([inventoryHeaders]),'mise-inventory-template.csv','text/csv;charset=utf-8')}>Download CSV template</button></div>
      </>}
      {view === 'recipes' && <><div className="filter-row"><div className="filter-tabs">{[['all','All recipes',costed.length],['on-target','On target',costed.filter(r => r.cost.status === 'on-target').length],['review','Review margin',reviewCosts.length],['incomplete','Missing inputs',needsCost.length]].map(([key,label,count]) => <button key={key} className={filter === key ? 'selected' : ''} onClick={() => setFilter(String(key))}>{label}<span>{count}</span></button>)}</div><Badge tone="good">Target {state.settings.targetFoodCost}%</Badge></div><section className="panel table-panel">{costed.length ? <RecipeTable rows={costed.filter(r => matches(`${r.recipe.name} ${r.recipe.category}`) && (filter === 'all' || r.cost.status === filter))} inspect={id => setModal({type:'detail',id})} edit={id => setModal({type:'recipe',id})} busy={busy}/> : <Empty icon={<BookOpen size={34}/>} title="Know what every plate costs" text="Cost the entire batch, divide by its yield, and compare each portion with its selling price." action={primaryButton('recipe','Add recipe')}/>}</section><div className="inline-page-note"><Info size={15}/>Contribution is selling price minus ingredient cost, before labour, overhead, and taxes.</div></>}
      {view === 'prep' && <><div className="filter-row"><div className="filter-tabs">{[['all','All dates'],['today','Today + overdue']].map(([key,label]) => <button key={key} className={filter === key ? 'selected' : ''} onClick={() => setFilter(key)}>{label}</button>)}</div><span className="muted-text">{activePrep.length} outstanding today / overdue</span></div><div className="prep-board">{(['todo','doing','done'] as const).map((status,index) => { const tasks = state.prep.filter(t => t.status === status && matches(`${t.name} ${t.station} ${t.assignee}`) && (filter !== 'today' || t.due === today || t.due !== null && t.due < today && t.status !== 'done')).sort((a,b) => (a.due ?? '9999').localeCompare(b.due ?? '9999') || Number(b.priority === 'high') - Number(a.priority === 'high')); return <section className="prep-column" key={status}><div className="column-heading"><span className={`column-dot c-${status}`}/><h2>{['To prepare','In progress','Ready'][index]}</h2><span>{tasks.length}</span></div>{tasks.map(task => <article className="task-card" key={task.id}><div className="task-card-top"><Badge tone={task.priority === 'high' ? 'warning' : 'neutral'}>{task.priority === 'high' ? 'High priority' : task.station || 'General prep'}</Badge><button className="icon-button" aria-label={`Edit ${task.name}`} onClick={() => setModal({type:'task',id:task.id})}><MoreHorizontal size={18}/></button></div><h3>{task.name}</h3><p>{task.quantity || 'Quantity not specified'}{task.priority === 'high' && task.station ? ` · ${task.station}` : ''}</p><div className="task-card-meta"><span className={task.due !== null && task.due < today && task.status !== 'done' ? 'warning-text' : ''}><CalendarDays size={13}/>{task.due === today ? 'Today' : task.due ?? 'Template · set service date'}{task.due !== null && task.due < today && task.status !== 'done' ? ' · overdue' : ''}</span><span>{task.assignee || 'Unassigned'}</span></div><div className="task-card-actions"><button className="text-button" disabled={busy} onClick={() => task.due === null ? setModal({type:'task',id:task.id}) : void save({ ...state, prep: state.prep.map(t => t.id === task.id ? { ...t, status: status === 'todo' ? 'doing' : status === 'doing' ? 'done' : 'todo' } : t) })}>{status === 'todo' ? <Play size={13}/> : status === 'doing' ? <Check size={14}/> : <RefreshCw size={13}/>} {status === 'todo' ? 'Start prep' : status === 'doing' ? 'Mark ready' : 'Reopen'}</button><button className="icon-button" disabled={busy} aria-label={`Delete task ${task.name}`} onClick={() => void deleteRecord('prep',task.id)}><Trash2 size={14}/></button></div></article>)}{!tasks.length && <div className="column-empty">{status === 'done' ? 'Ready prep will appear here.' : 'No tasks in this column.'}</div>}{status === 'todo' && <button className="add-card" disabled={busy} onClick={() => setModal({type:'task'})}><Plus size={16}/>Add prep task</button>}</section> })}</div></>}
      {view === 'orders' && <><div className="order-summary"><div><span className="eyebrow">ORDER FROM WHAT YOU NEED</span><h2>{low.length} ingredients below par.</h2><p>Create one draft per supplier. Items on open orders are excluded to prevent duplicate purchases.</p></div><button className="button primary" disabled={busy} onClick={() => void draftOrders()}><ShoppingCart size={17}/>Build draft orders</button></div><div className="filter-row"><div className="filter-tabs">{[['all','All orders'],['draft','Drafts'],['ordered','Ordered'],['received','Received']].map(([key,label]) => <button key={key} className={filter === key ? 'selected' : ''} onClick={() => setFilter(key)}>{label}</button>)}</div></div><section className="panel table-panel">{!state.orders.length ? <Empty icon={<ShoppingCart size={34}/>} title="Your next delivery starts here" text="Set ingredient pars, count your stock, and add pack prices. Mise will calculate the packs you need."/> : <div className="table-scroll"><table><thead><tr><th>Purchase order</th><th>Supplier</th><th>Created</th><th className="numeric">Estimated cost</th><th>Status</th><th>Action</th></tr></thead><tbody>{state.orders.filter(o => (filter === 'all' || o.status === filter) && matches(`${state.suppliers.find(s => s.id === o.supplierId)?.name ?? 'Unassigned'} ${o.lines.map(l=>l.name).join(' ')}`)).map(o => <tr key={o.id}><td><button className="item-name" onClick={() => setModal({type:'order',id:o.id})}>PO-{o.id.slice(0,8).toUpperCase()}</button><small>{o.lines.length} ingredients · {o.lines.reduce((s,l) => s+l.packs,0)} packs</small></td><td>{state.suppliers.find(s => s.id === o.supplierId)?.name ?? 'Unassigned supplier'}</td><td>{o.created}<small>{o.received ? `Received ${o.received}` : ''}</small></td><td className="numeric">{money(o.lines.reduce((sum,l) => sum+l.packs*l.unitPrice,0))}</td><td><Badge tone={o.status === 'received' ? 'good' : o.status === 'ordered' ? 'blue' : 'neutral'}>{o.status === 'draft' ? 'Draft' : o.status === 'ordered' ? 'Ordered' : 'Received'}</Badge></td><td><button className="text-button" onClick={() => setModal({type:'order',id:o.id})}>{o.status === 'draft' ? 'Review draft' : o.status === 'ordered' ? 'Receive delivery' : 'View receipt'}<ArrowRight size={14}/></button></td></tr>)}</tbody></table></div>}</section><div className="inline-page-note"><Info size={15}/>Orders are tracked here. Copy or export your order and send it to your supplier separately. Estimates exclude taxes and delivery fees.</div></>}
      {view === 'suppliers' && <div className="supplier-grid">{state.suppliers.filter(s => matches(`${s.name} ${s.contact} ${s.deliveryDays}`)).map(s => <section className="supplier-card" key={s.id}><div className="supplier-top"><span className="supplier-logo"><Truck size={23}/></span><div><h2>{s.name}</h2><p>{s.contact || 'Contact person not set'}</p></div><button className="icon-button" aria-label={`Edit ${s.name}`} onClick={() => setModal({type:'supplier',id:s.id})}><Pencil size={16}/></button></div><dl><div><dt>Delivery days</dt><dd>{s.deliveryDays || 'Not set'}</dd></div><div><dt>Order email</dt><dd>{s.email ? <a href={`mailto:${s.email}`}>{s.email}</a> : 'Not set'}</dd></div><div><dt>Phone</dt><dd>{s.phone || 'Not set'}</dd></div></dl>{s.notes && <p className="supplier-notes">{s.notes}</p>}<div className="supplier-footer"><span>{state.ingredients.filter(i=>i.supplierId===s.id).length} ingredients</span><button className="icon-button" disabled={busy} onClick={() => void deleteRecord('suppliers',s.id)} aria-label={`Delete supplier ${s.name}`}><Trash2 size={15}/></button></div></section>)}{!state.suppliers.length && <section className="panel wide-panel"><Empty icon={<Truck size={34}/>} title="Bring your suppliers together" text="Save contacts, delivery days, and order cut-offs, then link your ingredients." action={primaryButton('supplier','Add supplier')}/></section>}{state.suppliers.length > 0 && !state.suppliers.some(s=>matches(`${s.name} ${s.contact} ${s.deliveryDays}`)) && <div className="no-results">No suppliers match your search.</div>}</div>}
      {view === 'waste' && <><div className="waste-summary"><div><span className="eyebrow">RECORDED THIS MONTH</span><strong>{money(monthWaste.reduce((sum,w) => sum+(w.cost??0),0))}</strong><p>{monthWaste.length} entries{monthWaste.some(w=>w.cost===null) ? ' · unpriced entries excluded from value' : ' · valued when recorded'}</p></div><span className="waste-summary-icon"><Leaf size={40} strokeWidth={1.2}/></span><p>Track the reason.<br/>Find the pattern.<br/><strong>Prepare a little smarter.</strong></p></div><section className="panel table-panel">{!state.waste.length ? <Empty icon={<Leaf size={34}/>} title="Make waste visible" text="Record a quantity and reason. Stock adjusts immediately, and the cost stays in the log." action={primaryButton('waste','Record waste')}/> : <div className="table-scroll"><table><thead><tr><th>Date</th><th>Ingredient</th><th className="numeric">Quantity</th><th>Reason</th><th className="numeric">Recorded cost</th></tr></thead><tbody>{[...state.waste].sort((a,b)=>b.date.localeCompare(a.date)).filter(w=>matches(`${state.ingredients.find(i=>i.id===w.ingredientId)?.name} ${w.reason}`)).map(w => <tr key={w.id}><td>{w.date}</td><td className="item-name">{state.ingredients.find(i=>i.id===w.ingredientId)?.name ?? 'Ingredient'}</td><td className="numeric">{quantity(w.quantity,w.unit)}</td><td>{w.reason}</td><td className="numeric">{money(w.cost)}{w.cost===null && <small>Price missing when logged</small>}</td></tr>)}</tbody></table></div>}</section></>}
      {view === 'budget' && <BusinessPlanner state={state} busy={busy} save={save} demo={demo}/>}
      {view === 'launch' && <MenuLaunch state={state} busy={busy} save={save}/>}
      {view === 'billing' && <Subscription demo={demo}/>}
      {!demo&&(view === 'sales' || view === 'team' || view === 'sources') && <FabergeData key={view} view={view}/>}
      {view === 'settings' && <SettingsPane state={state} busy={busy} save={save} backup={() => download(JSON.stringify(state,null,2),`mise-kitchen-backup-${today}.json`,'application/json')} restore={() => backupInput.current?.click()} reset={() => setModal({type:'reset'})} sample={() => setModal({type:'sample'})}/>}
      </>}
      <footer className="kitchen-footer"><span>mise<span>.</span> KitchenSync · Early access</span><div><a href="/help">Help</a><a href="/privacy">Data notice</a><a href="/terms">Pilot terms</a></div></footer>
    </main></div>
    <input className="sr-only" tabIndex={-1} ref={fileInput} type="file" accept=".csv,text/csv" onChange={e => { void readImport(e.target.files?.[0],'inventory'); e.target.value='' }}/><input className="sr-only" tabIndex={-1} ref={backupInput} type="file" accept=".json,application/json" onChange={e => { void readImport(e.target.files?.[0],'backup'); e.target.value='' }}/>
    {notice && <div className="app-toast" role="status"><Info size={18}/><span>{notice}</span><button onClick={() => setNotice('')} aria-label="Dismiss notification"><X size={16}/></button></div>}
    {modal?.type === 'ingredient' && <IngredientEditor {...editorProps}/>}{modal?.type === 'recipe' && <RecipeEditor {...editorProps}/>}{modal?.type === 'supplier' && <SupplierEditor {...editorProps}/>}{modal?.type === 'task' && <PrepEditor {...editorProps}/>}{modal?.type === 'waste' && <WasteEditor {...editorProps}/>}
    {modal?.type === 'detail' && state.recipes.find(r=>r.id===modal.id) && <RecipeDetails recipe={state.recipes.find(r=>r.id===modal.id)!} state={state} busy={busy} close={() => setModal(null)} edit={() => setModal({type:'recipe',id:modal.id})} remove={() => { void deleteRecord('recipes',modal.id!).then(()=>setModal(null)) }}/>} 
    {modal?.type === 'order' && state.orders.find(o=>o.id===modal.id) && <OrderDetails key={modal.id} order={state.orders.find(o=>o.id===modal.id)!} {...editorProps}/>}
    {modal?.type === 'import' && importData && <FormDialog title={importData.kind === 'inventory' ? 'Review ingredient import' : 'Restore a kitchen backup'} description={importData.name} close={() => setModal(null)} busy={busy}><div className="import-preview"><strong>{importData.state.ingredients.length} ingredients</strong><span>{importData.state.recipes.length} recipes · {importData.state.suppliers.length} suppliers · {importData.state.prep.length} prep tasks</span><p>{importData.kind === 'inventory' ? 'Ingredients with the same name are updated; new names are added. Other kitchen records are kept. Check pack prices, quantities, and usable yield after importing.' : 'This replaces all current kitchen records with the backup. Download a backup of your current records first.'}</p></div><div className="form-footer"><button className="button secondary" disabled={busy} onClick={()=>setModal(null)}>Cancel</button><button className="button primary" disabled={busy} onClick={async()=>{ if(await save(importData.state)) {setModal(null);setImportData(null)} }}>{busy?'Saving…':importData.kind==='inventory'?'Import ingredients':'Replace kitchen records'}<ArrowRight size={15}/></button></div></FormDialog>}
    {modal?.type === 'sample' && <FormDialog title="Explore a sample kitchen" description="Illustrative records help you see how the tools work together." close={()=>setModal(null)} busy={busy}><div className="import-preview"><p>The sample includes eight ingredients, two recipes, a supplier, and three prep tasks. These are example prices and quantities.</p><strong>{anyRecords ? 'Loading the sample replaces your current records. Download a backup first.' : 'You can clear the sample in Settings whenever you are ready.'}</strong></div><div className="form-footer"><button className="button secondary" onClick={()=>setModal(null)} disabled={busy}>Cancel</button><button className="button primary" disabled={busy} onClick={async()=>{if(await save(sampleWorkspace())){setModal(null);navigate('overview')}}}>{busy?'Loading…':'Load sample kitchen'}<ArrowRight size={15}/></button></div></FormDialog>}
    {modal?.type === 'reset' && <FormDialog title="Start with an empty kitchen?" description="This clears ingredients, recipes, suppliers, prep, orders, and waste records." close={()=>setModal(null)} busy={busy}><div className="import-preview"><p>Download a backup first if you want to keep these records. Your kitchen name and target will be kept.</p></div><div className="form-footer"><button className="button secondary" onClick={()=>setModal(null)} disabled={busy}>Cancel</button><button className="button danger" disabled={busy} onClick={async()=>{if(await save({...emptyWorkspace(),settings:state.settings})){setModal(null);navigate('overview')}}}>{busy?'Clearing…':'Clear kitchen records'}</button></div></FormDialog>}
  </div>
}

function Metric({ icon, label, value, note, onClick }: { icon: ReactNode; label: string; value: string; note: string; onClick: () => void }) { return <button className="metric-card" onClick={onClick}><div><span>{label}</span><i>{icon}</i></div><strong>{value}</strong><small>{note}</small></button> }
function Attention({ icon, title, text, tone, onClick }: { icon: ReactNode; title: string; text: string; tone: string; onClick: () => void }) { return <button className="attention-item" onClick={onClick}><span className={`attention-icon ${tone}`}>{icon}</span><div><strong>{title}</strong><small>{text}</small></div><ChevronRight size={16}/></button> }
function RecipeTable({ rows, inspect, edit, busy }: { rows: { recipe: Recipe; cost: ReturnType<typeof costRecipe> }[]; inspect: (id: string) => void; edit: (id: string) => void; busy: boolean }) { return <div className="table-scroll"><table className="recipe-table"><thead><tr><th>Recipe</th><th className="numeric">Selling price</th><th className="numeric">Cost / portion</th><th>Food cost</th><th className="numeric">Contribution</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{rows.map(({recipe,cost})=><tr key={recipe.id}><td><button className="item-name" onClick={()=>inspect(recipe.id)}>{recipe.name}</button><small>{recipe.category || 'Uncategorized'} · {recipe.portions===null?'Yield missing':`${recipe.portions} portions / batch`}</small></td><td className="numeric">{money(recipe.sellingPrice)}</td><td className="numeric">{money(cost.portionCost)}</td><td><div className="foodcost-cell"><strong>{cost.foodCost===null?'—':`${cost.foodCost.toFixed(1)}%`}</strong><span className={`foodcost-bar ${cost.status}`}><i style={{width:`${Math.min(100,cost.foodCost??0)}%`}}/></span></div></td><td className="numeric">{money(cost.contribution)}</td><td><Badge tone={cost.status==='on-target'?'good':cost.status==='review'?'warning':'neutral'}>{cost.status==='on-target'?'On target':cost.status==='review'?'Review margin':'Missing inputs'}</Badge></td><td><button className="icon-button" disabled={busy} aria-label={`Edit recipe ${recipe.name}`} onClick={()=>edit(recipe.id)}><Pencil size={15}/></button></td></tr>)}</tbody></table>{!rows.length && <div className="no-results">No recipes match this view.</div>}</div> }
function RecipeDetails({recipe,state,busy,close,edit,remove}:{recipe:Recipe;state:Workspace;busy:boolean;close:()=>void;edit:()=>void;remove:()=>void}) { const cost=costRecipe(recipe,state.ingredients,state.settings.targetFoodCost); return <FormDialog title={recipe.name} description={`${recipe.category || 'Recipe'} · ${recipe.portions ?? 'Unknown'} portions per batch`} close={close} busy={busy}><div className="cost-preview"><div><small>Cost / portion</small><strong>{money(cost.portionCost)}</strong></div><div><small>Food cost</small><strong>{cost.foodCost===null?'—':`${cost.foodCost.toFixed(1)}%`}</strong></div><div><small>Contribution</small><strong>{money(cost.contribution)}</strong></div><div><small>Price at {state.settings.targetFoodCost}%</small><strong>{money(cost.suggestedPrice)}</strong></div></div>{cost.issues.length>0 && <div className="validation-note"><Info size={17}/><div><strong>Complete these inputs</strong>{cost.issues.map(i=><span key={i}>{i}</span>)}</div></div>}<div className="table-scroll"><table><thead><tr><th>Batch ingredient</th><th className="numeric">Quantity</th><th className="numeric">Cost</th></tr></thead><tbody>{cost.lines.map(l=><tr key={l.id}><td>{l.name}</td><td className="numeric">{quantity(l.quantity,l.unit)}</td><td className="numeric">{money(l.cost)}</td></tr>)}</tbody></table></div>{recipe.source && <div className="source-stamp"><span className="badge warning">{recipe.source.status==='draft'?'Imported draft':'Imported reference'}</span><p>{recipe.source.detail}</p><a className="text-button" href={`/api/faberge/file?id=${encodeURIComponent(recipe.source.fileId)}`}><Download size={14}/>Original recipe document</a></div>}<p className="recipe-notes">{recipe.notes || 'No preparation notes yet.'}</p><div className="inline-note"><Info size={16}/>Contribution excludes labour, overhead, and taxes. Suggested price uses your food cost target.</div><div className="form-footer"><button className="button danger-text" disabled={busy} onClick={remove}><Trash2 size={15}/>Delete recipe</button><button className="button primary" onClick={edit} disabled={busy}><Pencil size={15}/>Edit costing</button></div></FormDialog> }

function OrderDetails({order,state,busy,save,close,notify}:{order:Order;state:Workspace;busy:boolean;save:(s:Workspace)=>Promise<boolean>;close:()=>void;notify:(s:string)=>void}) {
  const [lines,setLines]=useState(order.lines)
  const supplier=state.suppliers.find(s=>s.id===order.supplierId)
  async function store(status:'draft'|'ordered') { if(lines.some(l=>!Number.isInteger(l.packs)||l.packs<1)) return notify('Enter a whole number of packs greater than zero.'); if(await save({...state,orders:state.orders.map(o=>o.id===order.id?{...o,lines,status}:o)})) close() }
  async function receive(){try{if(await save(receiveOrder(state,order.id)))close()}catch(e){notify(e instanceof Error?e.message:'Review the order.')}}
  return <FormDialog title={`PO-${order.id.slice(0,8).toUpperCase()}`} description={`${supplier?.name ?? 'Unassigned supplier'} · ${order.created} · ${order.status}`} close={close} busy={busy}><div className="table-scroll"><table><thead><tr><th>Ingredient / purchase pack</th><th className="numeric">Packs</th><th className="numeric">Estimated cost</th></tr></thead><tbody>{lines.map((line,n)=><tr key={`${line.ingredientId}-${n}`}><td><strong>{line.name}</strong><small>{line.purchaseLabel} · {quantity(line.usablePerPack,line.unit)} usable / pack</small></td><td className="numeric">{order.status==='draft'?<input aria-label={`Packs of ${line.name}`} className="pack-input" type="number" min="1" max="1000000" step="1" disabled={busy} value={line.packs || ''} onChange={e=>setLines(old=>old.map((l,i)=>i===n?{...l,packs:Number(e.target.value)}:l))}/>:line.packs}</td><td className="numeric">{money(line.packs*line.unitPrice)}</td></tr>)}</tbody></table></div><div className="order-total"><span>Total estimate</span><strong>{money(lines.reduce((sum,l)=>sum+l.unitPrice*l.packs,0))}</strong></div><div className="inline-note"><Info size={16}/>{order.status==='ordered'?'Confirm that the full quantities arrived. Receiving adds usable quantities to stock once.':order.status==='received'?`This delivery was received on ${order.received}. Stock has already been updated.`:'This app does not send orders. Export the draft, contact your supplier, then mark it ordered.'}</div><div className="form-footer order-footer"><button className="button secondary" onClick={()=>download(csv([['ingredient','packs','purchase_pack','unit_price_cad','estimated_total_cad'],...lines.map(l=>[l.name,l.packs,l.purchaseLabel,l.unitPrice,l.packs*l.unitPrice])]),`mise-order-${order.id.slice(0,8)}.csv`,'text/csv;charset=utf-8')}><Download size={15}/>Export order</button>{order.status==='draft' && <><button className="button secondary" disabled={busy} onClick={()=>void store('draft')}>Save draft</button><button className="button primary" disabled={busy} onClick={()=>void store('ordered')}>{busy?'Saving…':'Mark ordered'}<Check size={15}/></button></>}{order.status==='ordered' && <button className="button primary" disabled={busy} onClick={()=>void receive()}>{busy?'Receiving…':'Confirm full delivery received'}<CheckCheck size={16}/></button>}{order.status==='received' && <button className="button primary" onClick={close}>Done</button>}</div></FormDialog>
}

function SettingsPane({state,busy,save,backup,restore,reset,sample}:{state:Workspace;busy:boolean;save:(s:Workspace)=>Promise<boolean>;backup:()=>void;restore:()=>void;reset:()=>void;sample:()=>void}) {
  const [name,setName]=useState(state.settings.kitchenName)
  const [target,setTarget]=useState(String(state.settings.targetFoodCost))
  async function submit(e:FormEvent){e.preventDefault();await save({...state,settings:{kitchenName:name.trim(),targetFoodCost:Number(target)}})}
  return <div className="settings-grid"><section className="panel settings-panel"><SectionTitle title="Kitchen preferences" subtitle="Your target is a planning goal you can adjust."/><form onSubmit={submit}><fieldset disabled={busy}><Field label="Kitchen name"><input required minLength={1} maxLength={120} value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Target food cost (%)" hint="Suggested selling price = portion cost ÷ (target ÷ 100)."><input required type="number" min="0.01" max="99.99" step="any" value={target} onChange={e=>setTarget(e.target.value)}/></Field><div className="settings-facts"><div><span>Currency</span><strong>CAD</strong></div><div><span>Kitchen timezone</span><strong>America/Toronto</strong></div></div></fieldset><button className="button primary" disabled={busy}>{busy?'Saving…':'Save preferences'}<Check size={15}/></button></form></section><section className="panel settings-panel"><SectionTitle title="Records & backups" subtitle="Keep a portable copy of your whole kitchen."/><div className="setting-action"><span className="setting-icon"><Download size={21}/></span><div><strong>Download a backup</strong><p>Ingredients, recipes, suppliers, prep, orders, and waste as JSON.</p></div><button className="button secondary small" onClick={backup}>Download</button></div><div className="setting-action"><span className="setting-icon"><Upload size={21}/></span><div><strong>Restore a backup</strong><p>Review a valid Mise backup before replacing current records.</p></div><button className="button secondary small" disabled={busy} onClick={restore}>Restore</button></div><div className="setting-action"><span className="setting-icon"><ChefHat size={21}/></span><div><strong>Explore a sample kitchen</strong><p>Example prices and recipes, clearly labelled as samples.</p></div><button className="button secondary small" disabled={busy} onClick={sample}>Explore</button></div><div className="setting-action"><span className="setting-icon"><Trash2 size={20}/></span><div><strong>Clear kitchen records</strong><p>Start fresh. Your kitchen name and target are kept.</p></div><button className="button danger-text small" disabled={busy} onClick={reset}>Clear</button></div></section><section className="panel settings-panel"><SectionTitle title="How the numbers work"/><dl className="calculation-guide"><div><dt>Usable unit cost</dt><dd>Full pack price ÷ (pack quantity × usable yield).</dd></div><div><dt>Portion cost</dt><dd>Total batch ingredient cost ÷ portions produced.</dd></div><div><dt>Food cost percentage</dt><dd>Portion cost ÷ selling price × 100. Missing inputs stay incomplete.</dd></div><div><dt>Contribution per portion</dt><dd>Selling price − ingredient cost. Labour, overhead, and taxes are additional costs.</dd></div><div><dt>Average food cost</dt><dd>A simple average of fully costed recipes, not weighted by sales.</dd></div><div><dt>Order quantities</dt><dd>Round up the stock shortfall to whole usable purchase packs.</dd></div></dl></section><section className="panel settings-panel"><SectionTitle title="Your existing app" subtitle="Built from Mise-KitchenSync on GitHub."/><div className="connection-note"><Database size={27}/><h3>Two data environments</h3><p>This private workspace saves its own kitchen records. Your repository’s original Supabase POS, guest, and integration modules are preserved in source and require their existing credentials. Their live data has not been imported or changed.</p><a className="button secondary" href="https://github.com/Robayth-Dhrubo/Mise-KitchenSync" target="_blank" rel="noopener noreferrer">View source repository <ArrowUpRight size={15}/></a></div><div className="inline-note"><ShieldCheck size={16}/>The private Site uses your ChatGPT sign-in. Only your account can access these records.</div></section></div>
}
